/**
 * mask() must stay linear on long non-whitespace runs. A prefix hit extends
 * to the end of its run; resuming the search one character later rescanned
 * the same run for every repeated prefix, so one long line could hold the
 * session for seconds in a single synchronous call no deadline can interrupt.
 */

import { describe, test, expect } from "vitest";
import { buildTable, mask, DEFAULT_PATTERNS } from "../src/mask.js";

const table = buildTable([], {}, DEFAULT_PATTERNS, { entropy: true });

function timed(text: string): { ms: number; out: string } {
  const t0 = performance.now();
  const out = mask(text, table).text;
  return { ms: performance.now() - t0, out };
}

describe("mask() stays fast on long runs", () => {
  test("a 100k-character run of a repeated key prefix finishes under 200 ms and is masked", () => {
    const run = "AK" + "IA";
    const text = run.repeat(25_000);
    expect(text.length).toBe(100_000);
    const { ms, out } = timed(text);
    expect(ms).toBeLessThan(200);
    expect(out).not.toContain(run);
  });

  test("a minified line full of a prefix inside ordinary words finishes under 200 ms", () => {
    // "props_" contains the service-account prefix "ops_".
    const text = "{props_a:1,props_b:2,props_c:3}".repeat(3_300);
    expect(text.length).toBeGreaterThan(100_000);
    const { ms } = timed(text);
    expect(ms).toBeLessThan(200);
  });

  test("a repeated named value is still found everywhere it occurs", () => {
    const named = buildTable(["X_TOKEN"], { X_TOKEN: "veiltest-synthetic-value-42" }, DEFAULT_PATTERNS, { entropy: true });
    const text = "a veiltest-synthetic-value-42 b veiltest-synthetic-value-42 c";
    const out = mask(text, named).text;
    expect(out).not.toContain("veiltest-synthetic-value-42");
    expect(out.startsWith("a ")).toBe(true);
    expect(out).toContain(" b ");
    expect(out.endsWith(" c")).toBe(true);
  });
});
